{
  "description": "The creature is a four-legged, shaggy-coated mammal shown in right-facing side profile standing on a small patch of dirt with sparse tufts of grass. It has the overall body, head, legs and tail of a domestic goat covered in long, coarse brown fur that is darker on the neck, back and legs and pale cream-white on the belly and inner flank, with a bearded chin and two curved horns. Covering the entire dorsal midsection from just behind the shoulders to above the hindquarters, sitting on top of the fur, is a large, domed, dark brown turtle/tortoise carapace with a distinct pattern of polygonal scutes.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat head with short brown fur, a lighter muzzle with a dark nose and mouth, a visible dark eye, and long hair forming a beard under the chin",
      "where": "at the front right end of the body, held upright on the neck"
    },
    {
      "part": "horns",
      "looks_like": "two thick, ridged, backward-curving horns, brown with darker annular rings and pointed tips",
      "where": "on top of the head, one on each side, curving back and slightly outward"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, fur-covered ears with visible inner ear detail",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "long, shaggy, coarse brown fur forming a thick mane and chest ruff and continuing as shaggy coat over the neck, shoulders, sides, and thighs",
      "where": "along the dorsal neck, chest, sides and legs, surrounding the shell and covering the body"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, straight, shaggy-furred legs, brown with dense hair",
      "where": "under the body, two forelegs under the chest and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "cloven hooves, dark brown to black, with two distinct toes per foot",
      "where": "at the bottom tip of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, bushy, shaggy brown tail with long hair",
      "where": "at the rear left end of the body above the hindlegs"
    },
    {
      "part": "shell",
      "looks_like": "large, oval, highly domed hard carapace, dark brown to blackish with lighter brown edges",
      "where": "covering the back, sitting on top of the fur from behind the shoulders to in front of the tail"
    },
    {
      "part": "plates",
      "looks_like": "polygonal scutes with concentric growth rings and raised pyramidal centers, arranged in longitudinal rows to form the shell surface",
      "where": "tiled across the entire outer surface of the shell"
    },
    {
      "part": "markings",
      "looks_like": "pale cream-white fur contrasting with the darker brown outer coat",
      "where": "on the belly, lower flank and inner thigh area"
    }
  ],
  "attached_objects": [
    "large domed turtle/tortoise carapace sitting on top of the back fur, not fused to the skin, with its lower edge resting on the shaggy coat"
  ],
  "animals": [
    "goat",
    "turtle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
